#!/bin/zsh
# Literally the repro published in the issue, executed as written. NO scripts from this repo are
# involved: the prompt is generated by an inline python3 heredoc and requests go through curl.
#
# The two servers differ in exactly one thing: --kv-disk-dir. That is the whole point of the repro --
# if completions differ, it cannot be blamed on cache CONTENTS, because nothing is ever loaded here.
#
# Runs against the b3f5018 build (a clean checkout of origin/main, built from an unmodified tree),
# which is what a maintainer gets from `git clone && make`. ALWAYS restores production on exit.
set -u
WT=/Users/naz/Projects/ds4-ab-upstream
MODEL=gguf/Qwen3.8-Flash-Next-Q4.gguf
OUT=/Users/naz/Projects/ds4/.codebase-memory/20261118-kvstorm/runs/repro-curl
PORT=8079
REPO=/Users/naz/Projects/ds4
say() { echo "$(date '+%H:%M:%S') $*"; }

restore_prod() {
  pkill -f "ds4-server --model $MODEL --ctx 65536 --port $PORT" 2>/dev/null
  sleep 5
  cd $REPO
  ./ds4-server.sh start-qwen >> $OUT/runner.log 2>&1
  for i in {1..60}; do
    curl -s -m 5 -o /dev/null http://127.0.0.1:8002/v1/models && { say "prod restored on :8002"; return; }
    sleep 5
  done
  say "WARNING: prod did not answer within 5 min"
}
mkdir -p $OUT
trap restore_prod EXIT

cd $REPO || exit 2
say "stopping production (idle-verified before launch)"
./ds4-server.sh stop >> $OUT/runner.log 2>&1
sleep 4
unset DS4_API_KEY QWEN_API_KEY QWEN_SUBSCRIPTION_KEY

# ---------------------------------------------------------------- prompt (deterministic bytes)
# 76,000 chars of one fixed sentence, repeated then truncated: no tokeniser, no corpus file, no
# measured constants. Anyone, on any commit, gets the same bytes and the same sha256.
python3 - "$OUT" <<'PY'
import hashlib, json, os, sys
out = sys.argv[1]
SENT = ("The catchment's baseflow is sustained by fractured bedrock rather than soil moisture, "
        "which decouples stream response from rainfall intensity. ")
UNIT = SENT * (76000 // len(SENT) + 1)
for i in range(2):
    # A distinct header per prompt: two independent samples, not one prompt reported twice.
    doc = ("Archive %d. " % i) + UNIT[:76000]
    msgs = [{"role": "system", "content": doc},
            {"role": "user", "content": "In one paragraph, what single factor governs the effect "
                                        "described above, and why?"}]
    body = json.dumps({"model": "default", "messages": msgs, "temperature": 0,
                       "max_tokens": 256, "stream": False,
                       "chat_template_kwargs": {"enable_thinking": False}})
    open("%s/prompt%d.json" % (out, i), "w").write(body)
    print("  prompt%d: %d body bytes, doc sha256=%s"
          % (i, len(body), hashlib.sha256(doc.encode()).hexdigest()[:16]))
PY

# ------------------------------------------------------------------- engine runner (twice, 1 flag differs)
run_phase() {   # $1 = label, $2.. = extra server flags
  local label=$1; shift
  : > $OUT/server-$label.log
  cd $WT || exit 2
  ./ds4-server --model $MODEL --ctx 65536 --port $PORT "$@" >> $OUT/server-$label.log 2>&1 &
  local pid=$!
  for i in {1..120}; do
    curl -s -m 5 -o /dev/null http://127.0.0.1:$PORT/v1/models && break
    kill -0 $pid 2>/dev/null || { say "engine $label died"; return 1; }
    sleep 5
  done
  say "phase $label up (pid $pid, flags: $*)"
  for p in 0 1; do
    for rep in 1 2; do                       # rep 2 proves the phase is itself deterministic
      curl -s -m 600 -H 'Content-Type: application/json' \
        -d @$OUT/prompt$p.json http://127.0.0.1:$PORT/v1/chat/completions \
        > $OUT/resp-$label-p$p-r$rep.json
      python3 -c "
import json,sys
d=json.load(open('$OUT/resp-$label-p$p-r$rep.json'))
t=(d['choices'][0]['message'].get('content') or '').strip()
open('$OUT/text-$label-p$p-r$rep.txt','w').write(t)
print('  $label p$p r$rep  prompt_tokens=%-6s completion_tokens=%-4s chars=%-5d %s'
      % (d['usage']['prompt_tokens'], d['usage']['completion_tokens'], len(t),
         repr(t[:52])))
"
    done
  done
  grep -a 'prompt start\|prefill chunk' $OUT/server-$label.log > $OUT/chunks-$label.txt
  kill $pid 2>/dev/null; wait $pid 2>/dev/null
  sleep 3
  cd $REPO || exit 2
}

rm -rf /tmp/repro-kv; mkdir -p /tmp/repro-kv
run_phase A-with-cache  --kv-disk-dir /tmp/repro-kv
run_phase B-no-cache

# ------------------------------------------------------------------------- what a maintainer needs
say "chunk schedules"
for L in A-with-cache B-no-cache; do
  echo "  --- $L"
  grep -a 'prefill chunk' $OUT/chunks-$L.txt | sed 's/.*prefill /    prefill /' | cut -c1-78
done
say "completions"
python3 - <<'PY'
import hashlib, os
out = "/Users/naz/Projects/ds4/.codebase-memory/20261118-kvstorm/runs/repro-curl"
def t(l, p, r=1):
    return open("%s/text-%s-p%d-r%d.txt" % (out, l, p, r), encoding="utf-8").read()
for p in (0, 1):
    a, b = t("A-with-cache", p), t("B-no-cache", p)
    for r in (1, 2):
        for lab in ("A-with-cache", "B-no-cache"):
            assert t(lab, p, r) == t(lab, p, 1), "%s p%d rep %d differs from rep 1" % (lab, p, r)
    print("  prompt %d:  identical across repeats within each phase" % p)
    print("    A: %s" % a[:120].replace("\n", " "))
    print("    B: %s" % b[:120].replace("\n", " "))
    print("    sha256 A=%s  B=%s  -> %s" % (hashlib.sha256(a.encode()).hexdigest()[:12],
                                            hashlib.sha256(b.encode()).hexdigest()[:12],
                                            "SAME" if a == b else "DIFFERENT"))
PY
rm -rf /tmp/repro-kv
say "done"
